/**
 * CARS Duel vetted topic pool persistence (migration 0018, WS6).
 *
 * The `cars_duel_topics` table is the persistence mirror of the vetted pool. Its
 * canonical source is content/cars-duel/topics.json, embedded into @mcat/content
 * (CARS_DUEL_TOPICS) and generated by scripts/generate-cars-duel-topics.mjs; the
 * seed loader below writes that same pool into Postgres so a DB-backed selector
 * reads an identical set. Idempotent: re-seeding upserts, so it is safe to run on
 * every deploy.
 *
 * FORMATIVE only — this table holds debate propositions + structural metadata, never
 * answer keys or mastery. Takes the same structural `Queryable` the other
 * repositories use, so a seed can join a migration/bootstrap transaction and a read
 * can run straight off the pool.
 */
import { CARS_DUEL_TOPICS } from '@mcat/content';
import { CarsDuelTopicSchema, type CarsDuelTopic } from '@mcat/contracts';
import type { Queryable } from './mastery-repository';

interface RawCarsDuelTopicRow extends Record<string, unknown> {
  topic_id: string;
  proposition: string;
  theme: string;
  argument_structure: string;
  difficulty: number;
  charge: string;
}

const toTopic = (raw: RawCarsDuelTopicRow): CarsDuelTopic =>
  CarsDuelTopicSchema.parse({
    id: raw.topic_id,
    proposition: raw.proposition,
    theme: raw.theme,
    argumentStructure: raw.argument_structure,
    difficulty: Number(raw.difficulty),
    charge: raw.charge,
  });

/**
 * Whether the pool table exists (migration 0018 applied). Callers that seed on
 * bootstrap probe this first so a content-only dev database (no authority tables)
 * degrades cleanly rather than throwing.
 */
export async function hasCarsDuelTopics(q: Queryable): Promise<boolean> {
  const { rows } = await q.query<{ present: boolean }>(
    `select exists (
       select 1 from information_schema.tables
        where table_schema = 'public' and table_name = 'cars_duel_topics'
     ) as present`,
  );
  return rows[0]?.present === true;
}

/**
 * Seed (idempotently upsert) the vetted CARS Duel topic pool. Defaults to the
 * canonical @mcat/content pool (i.e. content/cars-duel/topics.json); a caller/test
 * may pass an explicit set. One `unnest` statement writes the whole pool.
 */
export async function seedCarsDuelTopics(
  q: Queryable,
  topics: readonly CarsDuelTopic[] = CARS_DUEL_TOPICS,
): Promise<number> {
  if (topics.length === 0) return 0;
  await q.query(
    `insert into cars_duel_topics
       (topic_id, proposition, theme, argument_structure, difficulty, charge)
     select * from unnest(
       $1::text[], $2::text[], $3::text[], $4::text[], $5::int[], $6::text[]
     )
     on conflict (topic_id) do update set
       proposition = excluded.proposition,
       theme = excluded.theme,
       argument_structure = excluded.argument_structure,
       difficulty = excluded.difficulty,
       charge = excluded.charge`,
    [
      topics.map((t) => t.id),
      topics.map((t) => t.proposition),
      topics.map((t) => t.theme),
      topics.map((t) => t.argumentStructure),
      topics.map((t) => t.difficulty),
      topics.map((t) => t.charge),
    ],
  );
  return topics.length;
}

/** Read the seeded topic pool (validated back through its contract). */
export async function listCarsDuelTopics(q: Queryable): Promise<CarsDuelTopic[]> {
  const { rows } = await q.query<RawCarsDuelTopicRow>(
    `select topic_id, proposition, theme, argument_structure, difficulty, charge
       from cars_duel_topics
      order by topic_id`,
  );
  return rows.map(toTopic);
}
